package app.mangiamundo.core

/**
 * Timing of the startup loader: the logo globe gets three bites taken out of it.
 * Matches the loader generated by tools/build-logo.mjs (web and the Android splash icon).
 */
object StartupLoader {
    /** Whole globe before the first bite. */
    const val START_MS = 200L
    /** How long one bite takes to grow. */
    const val GROW_MS = 150L
    /** Time between the starts of two bites. */
    const val STEP_MS = 270L
    const val BITES = 3
    /** Until the last bite is in. */
    const val TOTAL_MS = START_MS + (BITES - 1) * STEP_MS + GROW_MS
    /** Fade-out once loading is done. */
    const val FADE_MS = 250L

    /**
     * Whether the loader stays: until the first data is in, and always until all bites are in,
     * so it plays once in full however fast the data arrives.
     */
    fun keep(ready: Boolean, elapsedMs: Long): Boolean = !ready || elapsedMs < TOTAL_MS
}
